'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const normalize=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const getStored=k=>{try{const v=JSON.parse(localStorage.getItem(k)||'[]');return Array.isArray(v)?v.filter(x=>games.some(g=>g.id===x)):[]}catch{return []}};
let favorites=getStored('nova-favorites'),recent=getStored('nova-recent');
const defaults={q:'',category:'Todos',console:'Todos',view:'all',device:'',input:'',access:'',verified:'',multiplayer:false,sort:'editorial'};
let state={...defaults},lastCatalog='/',visible=[],toastTimer,lastOpener=null;
const categories=['Todos',...new Set(games.map(g=>g.cat))];
// Console history of the reference title, not the execution platform of the web port.
const consoleGroups={
 'PS1':['port-3','port-14','port-15','port-16','port-19','lara','diablo','port-56','descent'],
 'PS2':['gta3','gtavc','port-5','nfsu2','nfsu','port-10','port-11','port-12','port-13','port-21','port-22','port-24','port-61'],
 'PS3':['port-0','port-12','port-13','port-23','port-25','port-26','port-27','port-44','port-71'],
 'Xbox':['gta3','gtavc','port-5','nfsu2','nfsu','port-9','port-10','port-54','port-61'],
 'Xbox 360':['port-0','port-5','port-11','port-12','port-13','port-25','port-26','port-27','port-44','port-71'],
 'Switch':['port-47','port-48','port-71'],
 'Nintendo 64':['classic-mario-kart-64','classic-ocarina-of-time','port-38','port-57','port-58'],
 'GameCube':['port-5','nfsu2','nfsu','port-10','port-36','port-39'],
 'Wii':['port-12','port-13','port-24','port-25','port-26','port-36','port-44'],
 'PSP':['port-4','port-11','port-12','port-13','port-22','port-23'],
 'Nintendo DS':['port-4'],
 'SNES':['port-40','prince'],
 'Mega Drive':['curated-sonic-3-knuckles','port-43','prince'],
 'Sega CD':['port-42'],
 'NES':['port-37']
};
consoleGroups['Navegador']=games.filter(g=>g.id.startsWith('web-')).map(g=>g.id);
const consoles=['Todos',...Object.keys(consoleGroups)];
const accessLabels={browser:'Versão web',own:'Exige arquivo original',demo:'Demo / shareware',runtime:'Via runtime',fan:'Recriação / fan game',unknown:'Consultar projeto'};
const statusLabels={gameplay:'Sessão curta observada',page:'Página verificada',launcher:'Launcher observado',limited:'Limitado no teste'};
function persist(){try{localStorage.setItem('nova-favorites',JSON.stringify(favorites));localStorage.setItem('nova-recent',JSON.stringify(recent))}catch{notify('Este navegador não permitiu salvar a biblioteca. Você pode exportá-la.')}}
function notify(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500)}
function art(g,large=false){const src=large?(g.screenshots?.[0]||g.art):g.art;const contain=g.artFit==='contain'&&src===g.art,retail=contain&&g.artKind==='original';return src?`${retail?`<span class="art-backdrop" aria-hidden="true" style="background-image:url('/${esc(src)}')"></span>`:''}<img class="game-art${contain?' contain-art':''}${retail?' retail-art':''}" src="/${esc(src)}" alt="${esc(g.name)} — ${g.artKind==='wordmark'?'marca de identificação do título':g.artKind==='project'?'imagem de apresentação do projeto':'imagem de identificação da edição original'}" width="${large?1440:460}" height="${large?810:215}" ${large?'fetchpriority="high"':'loading="lazy" decoding="async"'}>`:`<div class="fallback" style="--art-color:${esc(g.color)}"><span aria-hidden="true">N↗</span><strong>${esc(g.name.split(' · ')[0])}</strong></div>`}
function card(g){return `<article class="game-card" data-card="${g.id}"><div class="card-art"><a class="art-link" href="/jogos/${g.slug}/" data-game="${g.id}" aria-label="Ver ${esc(g.name)}">${art(g)}</a><button class="save-button" data-favorite="${g.id}" aria-pressed="${favorites.includes(g.id)}" aria-label="${favorites.includes(g.id)?'Remover dos favoritos':'Favoritar'} ${esc(g.name)}" title="${favorites.includes(g.id)?'Remover favorito':'Favoritar'}">${favorites.includes(g.id)?'♥':'♡'}</button></div><a class="game-title" href="/jogos/${g.slug}/" data-game="${g.id}">${esc(g.name)}</a>${g.access==='own'?'<span class="own-files-badge">Exige arquivo original</span>':''}<div class="card-meta"><span>${esc(g.cat)}</span>${g.access==='own'?'':`<span>${esc(accessLabels[g.access]||g.kind)}</span>`}</div><div class="card-device"><span>${g.devices.includes('Celular')?'Toque informado':g.devices.includes('PC')?'Computador':'Dispositivo a confirmar'}</span>${g.testLevel==='limited'?'<span>· Limite no teste</span>':''}</div></article>`}
const catalogNodes=new Map();
function renderGrid(list){const fragment=document.createDocumentFragment();for(const g of list){let node=catalogNodes.get(g.id);if(!node){const template=document.createElement('template');template.innerHTML=card(g);node=template.content.firstElementChild;catalogNodes.set(g.id,node)}const button=node.querySelector('[data-favorite]'),saved=favorites.includes(g.id);button.setAttribute('aria-pressed',String(saved));button.setAttribute('aria-label',(saved?'Remover dos favoritos ':'Favoritar ')+g.name);button.textContent=saved?'♥':'♡';fragment.appendChild(node)}$('#game-grid').replaceChildren(fragment)}
function countFilters(){return ['device','input','access','verified'].filter(k=>state[k]).length+(state.multiplayer?1:0)}
function urlForState(){const u=new URL('/',location.origin);for(const [k,v]of Object.entries(state))if(v!==defaults[k]&&v!==''&&v!==false)u.searchParams.set(k,String(v));return u.pathname+u.search}
function readState(){const p=new URLSearchParams(location.search);state={...defaults};for(const k of Object.keys(defaults))if(p.has(k))state[k]=k==='multiplayer'?p.get(k)==='true':p.get(k);if(!categories.includes(state.category))state.category='Todos';if(!consoles.includes(state.console))state.console='Todos';if(!['all','favorites','recent'].includes(state.view))state.view='all';if(!['editorial','az','za'].includes(state.sort))state.sort='editorial'}
function syncInputs(){for(const k of ['device','input','access','verified','sort'])$('#'+k).value=state[k];$('#search').value=state.q;$('#multiplayer').checked=state.multiplayer}
function updateNav(){ $$('[data-view]').forEach(a=>{if(a.dataset.view===state.view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});$('#favorite-count').textContent=favorites.length}
function filtered(){const query=normalize(state.q.trim());return games.filter(g=>(state.category==='Todos'||g.cat===state.category)&&(state.console==='Todos'||consoleGroups[state.console]?.includes(g.id))&&(!query||normalize(g.name+' '+g.searchText+' '+g.summary).includes(query))&&(state.view==='all'||(state.view==='favorites'?favorites:recent).includes(g.id))&&(!state.device||(state.device==='unknown'?g.devices.includes('Não confirmado'):g.devices.includes(state.device)))&&(!state.input||(state.input==='unknown'?g.inputs.includes('Não informado'):g.inputs.includes(state.input)))&&(!state.access||g.access===state.access)&&(!state.verified||g.testLevel===state.verified)&&(!state.multiplayer||g.multiplayer===true))}
function renderCatalog(){updateNav();$('#consoles').innerHTML=consoles.map(c=>`<button data-console="${esc(c)}" aria-pressed="${state.console===c}">${esc(c)}</button>`).join('');visible=filtered();if(state.sort==='az'||state.sort==='za')visible.sort((a,b)=>a.name.localeCompare(b.name,'pt-BR')*(state.sort==='za'?-1:1));else if(state.view==='recent')visible.sort((a,b)=>recent.indexOf(a.id)-recent.indexOf(b.id));$('#categories').innerHTML=categories.map(c=>`<button data-category="${esc(c)}" aria-pressed="${state.category===c}">${esc(c)}</button>`).join('');$('#catalog-title').textContent=state.view==='favorites'?'Os seus favoritos.':state.view==='recent'?'Seus últimos destinos.':'Encontre seu próximo clássico.';$('#catalog-description').textContent=state.view==='favorites'?'Sua seleção, salva neste navegador.':state.view==='recent'?'Projetos que você abriu pelo NOVA PLAY. Abrir um link não confirma uma partida.':'Explore os projetos. Confira os requisitos. Escolha seu próximo play.';$('#result-count').textContent=visible.length+(visible.length===1?' experiência':' experiências');$('#filter-count').textContent=countFilters()?`(${countFilters()})`:'';renderGrid(visible);$('#empty').hidden=visible.length!==0;$('#empty-title').textContent=state.view==='favorites'&&!favorites.length?'Seus próximos favoritos começam aqui.':state.view==='recent'&&!recent.length?'Sua jornada ainda vai começar.':'Nenhum jogo com esses filtros.';$('#empty-description').textContent=state.view==='favorites'&&!favorites.length?'Toque no coração de um jogo para guardá-lo nesta biblioteca.':'Explore o catálogo ou remova alguns filtros para descobrir outros jogos.';$('#clear-filters').hidden=!state.q&&state.category==='Todos'&&state.console==='Todos'&&!countFilters();$('#random').disabled=!visible.length;$('#active-filters').innerHTML=[...(state.console!=='Todos'?[['console',`Console: ${state.console}`]]:[]),...(state.q?[['q',`Busca: ${state.q}`]]:[]),...['device','input','access','verified'].filter(k=>state[k]).map(k=>[k,k==='access'?accessLabels[state[k]]:k==='verified'?statusLabels[state[k]]:state[k]==='unknown'?'Não confirmado':state[k]]),...(state.multiplayer?[['multiplayer','Multiplayer']]:[])].map(([k,v])=>`<button data-remove="${k}" aria-label="Remover filtro ${esc(v)}">${esc(v)} ×</button>`).join('');$('#home-section').hidden=state.view!=='all'||!!state.q||state.category!=='Todos'||state.console!=='Todos'||countFilters()>0;$('#catalog-title').setAttribute('aria-level',$('#home-section').hidden?'1':'2');}
function setState(changes,{replace=false,scroll=false}={}){Object.assign(state,changes);const url=urlForState();history[replace?'replaceState':'pushState']({},'',url);lastCatalog=url;syncInputs();showCatalog();if(scroll)$('#catalog').scrollIntoView({behavior:reducedMotion()?'instant':'smooth',block:'start'})}
function reducedMotion(){return matchMedia('(prefers-reduced-motion: reduce)').matches}
function showCatalog(){document.title='NOVA PLAY — Seu próximo clássico';$('#detail').hidden=true;$('#catalog').hidden=false;$('#closing').hidden=false;renderCatalog()}
function featureCheck(g){const webgpu='gpu'in navigator;const gpuMessage=g.graphics.includes('WebGPU')?(webgpu?'Este navegador expõe a API WebGPU. Isso não confirma um adaptador compatível ou desempenho suficiente.':'A API WebGPU não está disponível neste navegador. Este projeto pode não iniciar.'):'Este projeto não tem requisitos gráficos completos confirmados no catálogo.';return `<div class="compatibility"><strong>Seu navegador, neste momento</strong><span>${esc(gpuMessage)}${!isSecureContext?' A conexão atual não é um contexto seguro.':''}</span></div>`}
function fileGuide(g){if(g.access!=='own')return '';return `<section class="info-section file-guide" id="arquivos-originais"><span class="own-files-badge">Exige arquivo original</span><h2>Onde conseguir os arquivos</h2><p><strong>${esc(g.requirements)}</strong></p><p>${esc(g.fileGuide?.description||'Consulte o projeto para preparar os arquivos da sua cópia.')}</p><div class="file-guide-links">${(g.fileGuide?.links||[{label:'Instruções do projeto',url:g.source}]).map(l=>`<a class="source-link" href="${esc(l.url)}" target="_blank" rel="noopener noreferrer">${esc(l.label)} ↗</a>`).join('')}</div><p class="file-guide-note">O NOVA PLAY não hospeda os arquivos originais. Confira a edição e o formato exigidos antes de comprar ou importar.</p></section>`}
function detail(g,{focus=false}={}){lastOpener=document.activeElement;$('#home-section').hidden=true;$('#catalog').hidden=true;$('#closing').hidden=true;$('#detail').hidden=false;document.title=g.name+' — NOVA PLAY';const similar=games.filter(x=>x.id!==g.id&&x.cat===g.cat).slice(0,4);$('#detail').innerHTML=`<div class="breadcrumbs"><a href="${esc(lastCatalog)}" data-back>← Voltar ao catálogo</a><span>/</span><a href="/?category=${encodeURIComponent(g.cat)}" data-category-link="${esc(g.cat)}">${esc(g.cat)}</a><span>/</span><span>${esc(g.name)}</span></div><div class="detail-layout"><div><div class="detail-visual">${art(g,true)}</div>${g.screenshots?.length?`<div class="screens">${g.screenshots.map((s,i)=>`<a href="/${esc(s)}" target="_blank" rel="noopener" aria-label="Ampliar imagem ${i+1} de ${esc(g.name)}"><img src="/${esc(s)}" alt="Cena da edição original de ${esc(g.name)}, imagem ${i+1}" width="720" height="405" loading="lazy"></a>`).join('')}</div>`:''}<div class="art-credit">${g.artSource?`${g.artKind==='wordmark'?'Marca de identificação do título.':g.artKind==='project'?'Imagem de apresentação do projeto.':'Arte de identificação da edição original.'} Não comprova o visual ou os recursos deste port. <a class="source-link" href="${esc(g.artSource)}" target="_blank" rel="noopener noreferrer">Fonte da imagem ↗</a>`:'Composição tipográfica do NOVA PLAY. Sem screenshot confirmado deste projeto.'}</div></div><div><span class="detail-eyebrow">${esc(g.cat.toUpperCase())} / ${esc(accessLabels[g.access]||g.kind)}</span><h1 tabindex="-1" id="game-title">${esc(g.name)}</h1><p class="summary">${esc(g.summary)}</p>${g.access==='own'?`<aside class="own-files-notice"><strong>Este jogo exige um arquivo original seu</strong><p>${esc(g.requirements)}</p><a href="#arquivos-originais">Onde conseguir e como preparar os arquivos ↓</a></aside>`:''}<div class="detail-actions"><a class="button primary" href="${esc(g.url)}" target="_blank" rel="noopener noreferrer" data-launch="${g.id}">Abrir jogo no projeto ↗</a><button class="button subtle" data-favorite="${g.id}" aria-pressed="${favorites.includes(g.id)}">${favorites.includes(g.id)?'♥ Salvo':'♡ Favoritar'}</button><button class="button subtle" data-share="${g.id}" aria-label="Compartilhar ${esc(g.name)}">Compartilhar</button></div><p class="external-note">Você vai abrir ${esc(new URL(g.url).hostname)} em outra aba. Confira os requisitos e o resultado da verificação abaixo.</p><div class="evidence-status"><strong>${esc(statusLabels[g.testLevel])} · ${esc(new Intl.DateTimeFormat('pt-BR').format(new Date(g.checked+'T12:00:00')))}</strong><p>${esc(g.verification)}</p></div></div></div><div class="detail-columns"><div>${fileGuide(g)}${g.award?`<section class="info-section"><h2>Reconhecimento do jogo original</h2><p>${esc(g.award.name)}. O prêmio pertence ao título original, não a esta adaptação web.</p><a class="source-link" href="${esc(g.award.source)}" target="_blank" rel="noopener noreferrer">Consultar premiação ↗</a></section>`:''}<section class="info-section"><h2>Antes de apertar play</h2><p>${esc(g.notes)}</p><ol><li>${g.access==='own'?'Separe os arquivos da sua cópia do jogo no formato indicado pelo projeto.':g.access==='runtime'?'No runtime, procure a demo ou a opção de importar os seus arquivos.':'Abra o projeto e consulte o conteúdo e os requisitos disponíveis.'}</li><li>Confira os controles e aguarde o carregamento. Alguns projetos baixam muitos dados na primeira sessão.</li><li>Use as opções do próprio jogo para exportar saves quando estiverem disponíveis. O NOVA PLAY não acessa partidas de outros sites.</li></ol></section><section class="info-section"><h2>Compatibilidade</h2>${featureCheck(g)}<p>Suporte declarado pelo projeto e detecção de API não equivalem a uma partida validada no seu aparelho.</p></section></div><div><section class="info-section"><h2>Ficha do projeto</h2><dl class="specs"><div><dt>Acesso</dt><dd>${esc(accessLabels[g.access]||g.kind)}</dd></div><div><dt>Arquivos</dt><dd>${esc(g.requirements)}</dd></div><div><dt>Dispositivos</dt><dd>${esc(g.devices.join(', '))}</dd></div><div><dt>Controles</dt><dd>${esc(g.inputs.join(', '))}</dd></div><div><dt>Multiplayer</dt><dd>${g.multiplayer===null?'Não confirmado':g.multiplayer?'Informado pelo projeto':'Não informado como disponível nesta versão'}</dd></div><div><dt>Gráficos</dt><dd>${esc(g.graphics)}</dd></div><div><dt>Fonte</dt><dd><a class="source-link" href="${esc(g.source)}" target="_blank" rel="noopener noreferrer">Projeto e requisitos ↗</a></dd></div></dl></section></div></div>${similar.length?`<section class="related"><h2>Mais para explorar em ${esc(g.cat.toLowerCase())}</h2><div class="game-grid">${similar.map(card).join('')}</div></section>`:''}`;updateNav();if(focus){window.scrollTo(0,0);$('#game-title').focus({preventScroll:true})}}
function navigateGame(id){const g=games.find(x=>x.id===id);if(!g)return;if(!location.pathname.startsWith('/jogos/'))lastCatalog=urlForState();history.pushState({},'',`/jogos/${g.slug}/`);detail(g,{focus:true})}
function route(){readState();syncInputs();const slug=location.pathname.match(/^\/jogos\/([^/]+)\/?$/)?.[1];if(slug){const g=games.find(x=>x.slug===slug);if(g)detail(g);else{showCatalog();notify('Esse jogo não está no catálogo.')}}else{lastCatalog=urlForState();showCatalog()}}
function toggleFavorite(id){if(!games.some(g=>g.id===id))return;const saved=favorites.includes(id);favorites=saved?favorites.filter(x=>x!==id):[...favorites,id];persist();updateNav();$$(`[data-favorite="${id}"]`).forEach(b=>{b.setAttribute('aria-pressed',String(!saved));if(b.classList.contains('save-button')){b.textContent=saved?'♡':'♥';b.setAttribute('aria-label',(saved?'Favoritar ':'Remover dos favoritos ')+games.find(g=>g.id===id).name)}else b.textContent=saved?'♡ Favoritar':'♥ Salvo'});if(state.view==='favorites'&&!location.pathname.startsWith('/jogos/'))renderCatalog();notify(saved?'Removido dos favoritos.':'Salvo nos seus favoritos.')}
function dialog(title,body){lastOpener=document.activeElement;$('#dialog-content').innerHTML=`<h2 id="dialog-title">${title}</h2>${body}`;$('#dialog').showModal()}
function closeDialog(){$('#dialog').close();if(lastOpener?.isConnected)lastOpener.focus()}
function research(){dialog('Pesquisa aberta. Critérios claros.',`<p>O NOVA PLAY reúne jogos de navegador, ports, demos, recriações e runtimes. As entradas têm condições diferentes; uma resposta de página não confirma uma partida.</p><div class="audit-grid"><div><b>${audit.indexEntries}</b><span>registros no índice de pesquisa</span></div><div><b>${audit.checkedDestinations}</b><span>destinos checados</span></div><div><b>${audit.httpSuccess}</b><span>páginas responderam HTTP 200</span></div><div><b>${games.length}</b><span>entradas selecionadas</span></div></div><p>Última checagem: 03/11/2026. O índice inclui duplicatas e projetos sem build web. No teste de navegador, GTA V abriu o launcher; NFS Most Wanted encerrou com código 0x1 ao iniciar solo; PES 6 encontrou um adaptador WebGPU indisponível.</p><p><strong>Não há certificação de partida para todo o catálogo.</strong> Os resultados e limitações aparecem nas fichas.</p><div class="dialog-actions"><a class="button primary" href="/research.json" download="nova-play-verificacao.json">Baixar verificação</a><a class="button subtle" href="/discovery.json" download="nova-play-pesquisa.json">Índice completo</a></div><p><a href="https://github.com/Carter54git/Ultimate-Catalog-Of-Web-Game-Ports" target="_blank" rel="noopener">Índice de projetos ↗</a> · <a href="https://portedgames.com/browser/" target="_blank" rel="noopener">PortedGames ↗</a> · <a href="/assets/sources.json" target="_blank">Fontes das imagens ↗</a></p><p>As imagens de editoras servem para identificar os títulos originais; podem representar outra edição e não garantem os recursos dos ports. Sem parceria presumida com as marcas.</p>`)}
function library(){dialog('Sua biblioteca, do seu jeito.',`<p><strong>${favorites.length} favoritos</strong> e <strong>${recent.length} destinos recentes</strong>, salvos neste navegador. Exporte um arquivo para levar sua seleção a outro aparelho.</p><div class="dialog-actions"><button class="button primary" data-action="export">Exportar favoritos</button><button class="button subtle" data-action="import">Importar biblioteca</button></div><p>O arquivo contém apenas identificadores dos jogos e sua lista de recentes. Não inclui saves, senhas ou dados dos projetos externos.</p><p id="import-message" role="status"></p>`)}
function downloadLibrary(){const blob=new Blob([JSON.stringify({format:'nova-play-library',version:1,exportedAt:new Date().toISOString(),favorites,recent},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='nova-play-biblioteca.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Biblioteca exportada.')}
async function shareGame(id){const g=games.find(g=>g.id===id),url=new URL(`/jogos/${g.slug}/`,location.origin).href;try{await navigator.clipboard.writeText(url);notify('Link do jogo copiado.')}catch{dialog('Compartilhar jogo',`<p>Copie o endereço para compartilhar ${esc(g.name)}.</p><input class="share-input" aria-label="Link do jogo" readonly value="${esc(url)}">`);$('.share-input').select()}}
document.addEventListener('click',e=>{const fav=e.target.closest('[data-favorite]');if(fav){toggleFavorite(fav.dataset.favorite);return}const game=e.target.closest('[data-game]');if(game&&!e.metaKey&&!e.ctrlKey&&!e.shiftKey&&!e.altKey&&e.button===0){e.preventDefault();navigateGame(game.dataset.game);return}const launch=e.target.closest('[data-launch]');if(launch){recent=[launch.dataset.launch,...recent.filter(x=>x!==launch.dataset.launch)].slice(0,40);persist();return}const share=e.target.closest('[data-share]');if(share){shareGame(share.dataset.share);return}const v=e.target.closest('[data-view]');if(v&&!e.ctrlKey&&!e.metaKey){e.preventDefault();setState({...defaults,view:v.dataset.view},{scroll:v.dataset.view!=='all'});window.scrollTo(0,0);return}const consoleButton=e.target.closest('[data-console]');if(consoleButton){setState(consoleButton.hasAttribute('data-classics')?{...defaults,console:'Nintendo 64'}:{console:consoleButton.dataset.console},{scroll:consoleButton.hasAttribute('data-classics')});return}const c=e.target.closest('[data-category]');if(c){setState({category:c.dataset.category});return}const cl=e.target.closest('[data-collection]');if(cl){setState({...defaults,...(cl.dataset.collection==='friends'?{multiplayer:true}:{category:cl.dataset.collection})},{scroll:true});return}const cb=e.target.closest('[data-category-link]');if(cb){e.preventDefault();setState({...defaults,category:cb.dataset.categoryLink},{scroll:true});return}const back=e.target.closest('[data-back]');if(back){e.preventDefault();history.pushState({},'',lastCatalog);route();$('#catalog').scrollIntoView();return}const rem=e.target.closest('[data-remove]');if(rem){setState({[rem.dataset.remove]:defaults[rem.dataset.remove]});return}const a=e.target.closest('[data-action]');if(a){const action=a.dataset.action;if(action==='research')research();if(action==='library')library();if(action==='reset'){if($('#dialog').open)closeDialog();setState({...defaults},{scroll:true})}if(action==='export')downloadLibrary();if(action==='import'){$('#import-file').value='';$('#import-file').click()}if(action==='privacy')dialog('Privacidade da biblioteca',`<p>Favoritos e recentes ficam no armazenamento local deste navegador. Esta versão do NOVA PLAY não tem cadastro, publicidade nem analytics próprios.</p><p>Abrir um jogo leva você a um serviço externo, com sua própria política de privacidade. Não acessamos seus saves ou dados desses serviços.</p><p>As fontes tipográficas são carregadas do Google Fonts. As imagens de identificação estão hospedadas junto do portal. A exportação da biblioteca só acontece quando você a solicita.</p><p>O histórico registra links abertos, e não tempo de jogo ou partidas concluídas.</p>`);}});
$('#search').addEventListener('input',e=>{if(location.pathname.startsWith('/jogos/'))state={...defaults};setState({q:e.target.value},{replace:true})});$('.search').onsubmit=e=>{e.preventDefault();$('#catalog').scrollIntoView()};for(const k of ['device','input','access','verified','sort'])$('#'+k).onchange=e=>setState({[k]:e.target.value});$('#multiplayer').onchange=e=>setState({multiplayer:e.target.checked});$('#filter-toggle').onclick=()=>{const expanded=$('#filter-toggle').getAttribute('aria-expanded')==='true';$('#filter-toggle').setAttribute('aria-expanded',String(!expanded));$('#filter-panel').hidden=expanded};$('#clear-filters').onclick=()=>setState({...defaults,view:state.view});$('#random').onclick=()=>{if(visible.length)navigateGame(visible[Math.floor(Math.random()*visible.length)].id)};$('#library-menu').onclick=library;$('#dialog-close').onclick=closeDialog;$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=$('#dialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog()}});$('#import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>1000000)throw Error('O arquivo é grande demais. Use uma exportação do NOVA PLAY.');const data=parseLibraryFile(await file.text(),games.map(g=>g.id));favorites=[...new Set([...favorites,...data.favorites])];recent=[...new Set([...recent,...data.recent])].slice(0,40);persist();updateNav();if($('#dialog').open)closeDialog();route();notify('Biblioteca importada. Sua seleção anterior foi preservada.')}catch(error){const m=$('#import-message');if(m){m.className='inline-error';m.textContent=error.message||'Não foi possível ler esse arquivo.'}else notify('Não foi possível importar esse arquivo.')}};document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('#dialog').open){e.preventDefault();$('#search').focus()}});window.addEventListener('popstate',()=>{if($('#dialog').open)closeDialog();route()});window.addEventListener('storage',e=>{if(['nova-favorites','nova-recent'].includes(e.key)){favorites=getStored('nova-favorites');recent=getStored('nova-recent');route()}});document.addEventListener('error',e=>{if(e.target.matches?.('.game-art')){const img=e.target;const fallback=document.createElement('div');fallback.className='fallback';const text=document.createElement('strong');text.textContent=img.alt.split(' — ')[0];fallback.append(text);img.replaceWith(fallback)}},true);route();

// One carousel instance survives catalog/detail navigation without duplicating timers.
(function initHeroCarousel(){
  const hero=$('.hero');
  if(!hero||hero.dataset.carouselReady)return;
  hero.dataset.carouselReady='true';
  const editorial=[
    {id:'port-0',heading:'A próxima aventura\njá tem endereço.',label:'GTA V'},
    {id:'gtavc',heading:'Luzes de neon.\nUma cidade para explorar.',label:'Vice City'},
    {id:'gta3',heading:'De volta às ruas\nde Liberty City.',label:'GTA III'},
    {id:'port-47',heading:'Um reino perdido.\nUm novo desafio.',label:'Hollow Knight'},
    {id:'port-48',heading:'A próxima conquista\nestá lá no alto.',label:'Celeste'},
    {id:'port-42',heading:'A nostalgia acelera.\nA próxima fase espera.',label:'Sonic CD'},
    {id:'quake',heading:'Entre na arena.\nReencontre um clássico.',label:'Quake III Arena'}
  ].map(slide=>({...slide,game:games.find(g=>g.id===slide.id)})).filter(slide=>slide.game&&(slide.game.screenshots?.[0]||slide.game.art));
  if(!editorial.length)return;
  const motion=matchMedia('(prefers-reduced-motion: reduce)');
  let index=0,timer=null,hovered=false,focused=false;
  const dots=$('#hero-dots');
  dots.innerHTML=editorial.map((slide,i)=>`<button class="hero-dot" type="button" data-slide="${i}" aria-label="Destaque ${i+1}: ${esc(slide.label)}" aria-pressed="${i===0}" ${i===0?'aria-current="true"':''}></button>`).join('');
  function canRotate(){return !hovered&&!focused&&!document.hidden&&!motion.matches&&!$('#home-section').hidden&&!$('#dialog').open;}
  function schedule(){clearTimeout(timer);timer=null;if(canRotate())timer=setTimeout(()=>show(index+1),6000);}
  function show(next){
    index=(next+editorial.length)%editorial.length;
    const slide=editorial[index],g=slide.game,image=$('#hero-image');
    image.hidden=false;image.src='/'+(g.screenshots?.[0]||g.art);image.alt=`${g.name} — imagem de identificação da edição original`;
    $('#hero-eyebrow').textContent=g.cat.toLocaleUpperCase('pt-BR');
    $('#hero-title').replaceChildren(...slide.heading.split('\n').flatMap((line,i)=>i?[document.createElement('br'),document.createTextNode(line)]:[document.createTextNode(line)]));
    $('#hero-game').textContent=g.id==='port-0'?'Grand Theft Auto V':g.name;
    $('#hero-description').textContent=g.id==='port-0'?'Los Santos chegou ao universo dos ports de navegador. Conheça o projeto e os requisitos antes de começar.':g.summary;
    $('#hero-cta').href='/jogos/'+g.slug+'/';$('#hero-cta').dataset.game=g.id;$('#hero-cta').innerHTML='Ver jogo <span aria-hidden="true">↗</span>';
    dots.querySelectorAll('button').forEach((dot,i)=>{dot.setAttribute('aria-pressed',String(i===index));if(i===index)dot.setAttribute('aria-current','true');else dot.removeAttribute('aria-current');});
    hero.dataset.slide=g.id;
    // Only the next image is preloaded; all remaining assets keep their normal loading behavior.
    const upcoming=editorial[(index+1)%editorial.length].game;
    const preload=new Image();preload.src='/'+(upcoming.screenshots?.[0]||upcoming.art);
    schedule();
  }
  dots.onclick=e=>{const dot=e.target.closest('[data-slide]');if(dot)show(Number(dot.dataset.slide));};
  hero.addEventListener('pointerenter',e=>{if(e.pointerType!=='touch'){hovered=true;schedule();}});
  hero.addEventListener('pointerleave',()=>{hovered=false;schedule();});
  hero.addEventListener('focusin',()=>{focused=true;schedule();});
  hero.addEventListener('focusout',e=>{focused=hero.contains(e.relatedTarget);schedule();});
  document.addEventListener('visibilitychange',schedule);
  motion.addEventListener('change',schedule);
  new MutationObserver(schedule).observe($('#home-section'),{attributes:true,attributeFilter:['hidden']});
  new MutationObserver(schedule).observe($('#dialog'),{attributes:true,attributeFilter:['open']});
  hero.querySelector('.hero-image').addEventListener('error',()=>{$('#hero-image').hidden=true;});
  show(0);
})();
